class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n, m = len(nums), len(changeIndices)
        def ok(t):
            last = [-1] * n
            for s in range(t):
                last[changeIndices[s] - 1] = s + 1
            D = sum(nums[i] for i in range(n) if last[i] == -1)
            k = sum(1 for i in range(n) if last[i] != -1)
            if D + 2 * k > t:
                return False
            pool, pend = D, 0
            for s in range(1, t + 1):
                idx = changeIndices[s - 1] - 1
                if last[idx] == s:
                    pend += 1
                elif pool:
                    pool -= 1
                elif pend:
                    pend -= 1
            return pool == 0 and pend == 0
        lo, hi, ans = 1, m, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if ok(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

