class Solution {
public:
    bool ok(int t, vector<int>& nums, vector<int>& ch, int n) {
        vector<int> last(n, -1);
        for (int s = 0; s < t; s++) last[ch[s] - 1] = s + 1;
        long long D = 0; int k = 0;
        for (int i = 0; i < n; i++) {
            if (last[i] == -1) D += nums[i]; else k++;
        }
        if (D + 2LL * k > t) return false;
        long long pool = D; long long pend = 0;
        for (int s = 1; s <= t; s++) {
            int idx = ch[s - 1] - 1;
            if (last[idx] == s) pend++;
            else if (pool) pool--;
            else if (pend) pend--;
        }
        return pool == 0 && pend == 0;
    }
    int earliestSecondToMarkIndices(vector<int>& nums, vector<int>& changeIndices) {
        int n = nums.size(), m = changeIndices.size();
        int lo = 1, hi = m, ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (ok(mid, nums, changeIndices, n)) { ans = mid; hi = mid - 1; }
            else lo = mid + 1;
        }
        return ans;
    }
};

