class Solution {
    private boolean ok(int t, int[] nums, int[] ch, int n) {
        int[] last = new int[n];
        Arrays.fill(last, -1);
        for (int s = 0; s < t; s++) last[ch[s] - 1] = s + 1;
        long D = 0; int k = 0;
        for (int i = 0; i < n; i++) {
            if (last[i] == -1) D += nums[i]; else k++;
        }
        if (D + 2L * k > t) return false;
        long pool = D, pend = 0;
        for (int s = 1; s <= t; s++) {
            int idx = ch[s - 1] - 1;
            if (last[idx] == s) pend++;
            else if (pool > 0) pool--;
            else if (pend > 0) pend--;
        }
        return pool == 0 && pend == 0;
    }
    public int earliestSecondToMarkIndices(int[] nums, int[] changeIndices) {
        int n = nums.length, m = changeIndices.length;
        int lo = 1, hi = m, ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (ok(mid, nums, changeIndices, n)) { ans = mid; hi = mid - 1; }
            else lo = mid + 1;
        }
        return ans;
    }
}

