var earliestSecondToMarkIndices = function(nums, changeIndices) {
    const n = nums.length, m = changeIndices.length;
    const ok = (t) => {
        const last = new Array(n).fill(-1);
        for (let s = 0; s < t; s++) last[changeIndices[s] - 1] = s + 1;
        let D = 0, k = 0;
        for (let i = 0; i < n; i++) {
            if (last[i] === -1) D += nums[i]; else k++;
        }
        if (D + 2 * k > t) return false;
        let pool = D, pend = 0;
        for (let s = 1; s <= t; s++) {
            const idx = changeIndices[s - 1] - 1;
            if (last[idx] === s) pend++;
            else if (pool > 0) pool--;
            else if (pend > 0) pend--;
        }
        return pool === 0 && pend === 0;
    };
    let lo = 1, hi = m, ans = -1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (ok(mid)) { ans = mid; hi = mid - 1; } else lo = mid + 1;
    }
    return ans;
};
